mapper.select:
/*
	SQL ID : DscsEzGraderDAO.selectEzgEvalRslt
	설명 : EZ-Grader 평가 결과 조회
*/
SELECT A.SCR
	 , A.EVLYN
FROM TB_LMS_DSCS_PTCP A
WHERE A.USER_ID = #{stdId}
	AND A.DSCS_ID = #{dscsId}

mapper.update:
/*
	SQL ID : DscsEzGraderDAO.initStdScoreToAllTeamMember
	설명 : EZ-Grader 선택 학습자 점수 초기화
	-- PTCP row 생성은 insertJoinUser에서 처리하고, 점수 초기화는 기존 row만 UPDATE한다.
*/
UPDATE TB_LMS_DSCS_PTCP
   SET SCR = #{scr}
	 , EVLYN = #{evlyn}
	 , MDFR_ID = #{rgtrId}
	 , MOD_DTTM = FN_DTTM()
 WHERE DSCS_ID = #{dscsId}

   AND TEAM_ID = #{teamId}


   AND USER_ID IN

	#{item}

/*
	SQL ID : DscsEzGraderDAO.updateJoinUserScore
	설명 : EZ-Grader 선택 학습자 평가 점수 저장
	-- PTCP row 생성은 insertJoinUser에서 처리하고, 점수 저장은 기존 row만 UPDATE한다.
*/
UPDATE TB_LMS_DSCS_PTCP
   SET SCR = #{scr}
	 , EVLYN = #{evlyn}
	 , MDFR_ID = #{mdfrId}
	 , MOD_DTTM = FN_DTTM()
 WHERE DSCS_ID = #{dscsId}

   AND USER_ID IN

	#{item}

mapper.delete:
/*
	SQL ID : DscsEzGraderDAO.deleteTeamStdScore
	설명 : 팀 평가 점수 삭제
*/
DELETE FROM TB_LMS_DSCS_PTCP
WHERE DSCS_ID = #{dscsId}

	AND TEAM_ID = #{teamId}


	AND USER_ID = #{stdId}

mapper.update:
