	SQL ID : DscsEzGraderDAO.insertStdScoreToAllTeamMember
	설명 : EZ-Grader 선택 학습자 평가 점수 저장
	-- 팀토론도 화면에서 선택된 학습자 목록만 기존 PTCP row 기준으로 UPDATE한다.
*/
UPDATE TB_LMS_DSCS_PTCP
   SET SCR = #{scr}
	 , EVLYN = #{evlyn}
	 , MDFR_ID = #{rgtrId}
	 , MOD_DTTM = FN_DTTM()
 WHERE DSCS_ID = #{dscsId}

   AND TEAM_ID = #{teamId}


   AND USER_ID IN

